-- 게시글
CREATE TABLE "blog_post_2" (
  "post_id" INTEGER NOT NULL GENERATED BY DEFAULT AS IDENTITY,
  "author_id" INTEGER,
  "post_title" CLOB,
  "published_dt" TIMESTAMP,
  "post_content" CLOB,
  PRIMARY KEY ("post_id")
);

COMMENT ON TABLE "blog_post" IS '게시글2';

COMMENT ON COLUMN "blog_post"."post_id" IS '게시글2 아이디';

COMMENT ON COLUMN "blog_post"."author_id" IS '저자2 아이디';

COMMENT ON COLUMN "blog_post"."post_title" IS '게시글 제목';

COMMENT ON COLUMN "blog_post"."published_dt" IS '공개 날짜';

COMMENT ON COLUMN "blog_post"."post_content" IS '게시글 내용';